<?php
require_once dirname(__DIR__).'/includes/bootstrap.php';require_module('approvals');$pageTitle='Approval Management';$activeMenu='approvals';
$sql="SELECT a.*,COALESCE(b.description,e.description) description,COALESCE(b.allocated_amount,e.amount) amount,COALESCE(db.name,de.name) department,COALESCE(b.budget_code,e.expense_code) request_code,CONCAT(u.first_name,' ',u.last_name) submitter FROM approvals a LEFT JOIN budgets b ON a.request_type='budget' AND b.id=a.request_id LEFT JOIN expenses e ON a.request_type='expense' AND e.id=a.request_id LEFT JOIN departments db ON db.id=b.department_id LEFT JOIN departments de ON de.id=e.department_id JOIN users u ON u.id=a.submitted_by";$params=[];$conds=[];if(!is_admin()){if(role_name()==='Finance Manager'){$conds[]="a.current_stage='finance'";}else{$conds[]="a.current_stage='department_manager'";$conds[]='COALESCE(b.department_id,e.department_id)=?';$params[]=(int)current_user()['department_id'];}}if($conds)$sql.=' WHERE '.implode(' AND ',$conds);$sql.=' ORDER BY (a.status="Pending") DESC,a.id DESC';$s=db()->prepare($sql);$s->execute($params);$rows=$s->fetchAll();
require ROOT_PATH.'/includes/header.php';?>
<div class="page-head"><div><h1>Approval Management</h1><p>Two-stage authorization queue: department manager review followed by Finance approval.</p></div><span class="badge bg-warning-subtle text-warning p-2"><?=count(array_filter($rows,fn($r)=>$r['status']==='Pending'))?> pending in your queue</span></div><div class="info-banner mb-3"><i class="fa-solid fa-diagram-project me-2"></i><strong>Workflow:</strong> Employee Request → Department Manager → Finance Approval → Approved</div><div class="card-panel"><div class="card-body"><div class="table-responsive"><table class="table data-table"><thead><tr><th>Request</th><th>Type</th><th>Department</th><th>Description</th><th class="text-end">Amount</th><th>Submitted By</th><th>Current Stage</th><th>Status</th><th class="no-print">Action</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td class="fw-semibold text-primary"><?=e($r['request_code']??('#'.$r['request_id']))?></td><td><?=e(ucfirst($r['request_type']))?></td><td><?=e($r['department']??'—')?></td><td><?=e($r['description']??'')?></td><td class="text-end"><?=money($r['amount'])?></td><td><?=e($r['submitter'])?></td><td><?=e(ucwords(str_replace('_',' ',$r['current_stage'])))?></td><td><?=status_badge($r['status'])?></td><td class="no-print"><div class="d-flex gap-1"><a class="btn btn-sm btn-light border" href="<?=e(url('approvals/history.php?id='.$r['id']))?>" title="History"><i class="fa-solid fa-clock-rotate-left"></i></a><?php if($r['status']==='Pending'):?><button class="btn btn-sm btn-success" data-bs-toggle="modal" data-bs-target="#actionModal" data-id="<?=$r['id']?>" data-action="approve"><i class="fa-solid fa-check"></i></button><button class="btn btn-sm btn-danger" data-bs-toggle="modal" data-bs-target="#actionModal" data-id="<?=$r['id']?>" data-action="reject"><i class="fa-solid fa-xmark"></i></button><?php endif;?></div></td></tr><?php endforeach;?></tbody></table></div></div></div>
<div class="modal fade" id="actionModal" tabindex="-1"><div class="modal-dialog"><div class="modal-content"><form method="post" action="<?=e(url('approvals/action.php'))?>"><div class="modal-header"><h5 class="modal-title">Process Approval</h5><button class="btn-close" data-bs-dismiss="modal"></button></div><div class="modal-body"><?=csrf_field()?><input type="hidden" name="approval_id" id="approvalId"><input type="hidden" name="action" id="approvalAction"><label class="form-label">Remarks</label><textarea class="form-control" name="remarks" rows="4" placeholder="Add review comments or rejection reason..."></textarea></div><div class="modal-footer"><button type="button" class="btn btn-light" data-bs-dismiss="modal">Cancel</button><button class="btn btn-primary" id="actionSubmit">Continue</button></div></form></div></div></div>
<?php $pageScripts='<script>document.getElementById("actionModal").addEventListener("show.bs.modal",e=>{const b=e.relatedTarget;const a=b.dataset.action;document.getElementById("approvalId").value=b.dataset.id;document.getElementById("approvalAction").value=a;document.getElementById("actionSubmit").textContent=a==="approve"?"Approve Request":"Reject Request";document.getElementById("actionSubmit").className="btn "+(a==="approve"?"btn-success":"btn-danger");});</script>';require ROOT_PATH.'/includes/footer.php';?>
